		DELETE FROM `play_jobs_ranks` WHERE `play_jobs_ranks`.`job` = JobId AND `play_jobs_ranks`.`rank` = rank;
        UPDATE `play_jobs_ranks` SET `play_jobs_ranks`.`rank` = `play_jobs_ranks`.`rank`-1 WHERE `play_jobs_ranks`.`job` = JobId AND `play_jobs_ranks`.`rank` > rank ORDER BY `play_jobs_ranks`.`rank` ASC;
