    END IF;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `ModifMember` (`oldrank` INT, `newrank` INT, `JobId` INT, `UserId` INT)  BEGIN
	IF(newrank > 0 && oldrank > 0 && JobId > 0 && UserId > 0) THEN
    
        UPDATE `group_memberships` SET `rank` = newrank WHERE `group_id` = JobId AND `rank` = oldrank AND `user_id` = UserId;
        
	END IF;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `ModifRank` (`oldrank` INT, `newrank` INT, `JobId` INT)  BEGIN
