        UPDATE `play_jobs_ranks` SET `rank` = 0 WHERE `job` = JobId AND `rank` = newrank;
        UPDATE `play_jobs_ranks` SET `rank` = newrank WHERE `job` = JobId AND `rank` = oldrank;
        UPDATE `play_jobs_ranks` SET `rank` = oldrank WHERE `job` = JobId AND `rank` = 0;
        
