        UPDATE `group_memberships` SET `rank` = newrank WHERE `group_id` = JobId AND `rank` = oldrank;
        UPDATE `group_memberships` SET `rank` = oldrank WHERE `group_id` = JobId AND `rank` = 0;
        
	END IF;
END$$

