INSERT INTO `moderation_presets` (`id`, `type`, `message`, `enabled`) VALUES
(1, 'room', 'El contenido de la sala no cumple con las normas de HabbStory.', '1'),
(3, 'user', 'No repitas el mismo signo en muchas ocasiones ya que se considera como spam, y seras mutead@.', '1'),
(4, 'user', 'Por favor envie pantallazos (capturas de pantalla) con las pruebas de que usted fue timado a un moderador.', '1'),
(5, 'user', 'Da click sobre el usuario y luego en ignorar para evitar problemas de esta persona en el futuro.', '1'),
(6, 'user', 'Please suggest, ask, or request about it on BoonBoards.com under the Help & Support section.', '1'),
(7, 'user', 'Tus acciones y/o lenguaje es inaceptable para HabbStory. Por favor, moderate o los moderadores tomaran medidas sobre ti.', '1'),
(8, 'user', 'Que pasooo!. Tu usuario contiene caracteres extraños o simplemente no cumple con las normas. Por favor cambialo o seras banead@ de HabbStory.', '1');
