INSERT INTO `play_internet` (`id`, `url`, `name`, `description`, `author_id`, `code`) VALUES
(1, 'www.eyefind.info', 'Eyefind', 'Búsquedas, publicidad y aplicaciones', 0, '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\'utf-8\'>\r\n    <meta http-equiv=\'X-UA-Compatible\' content=\'IE=edge\'>\r\n    <title>Eyefind</title>\r\n    <meta name=\'viewport\' content=\'width=device-width, initial-scale=1\'>\r\n\r\n    <!-- Font Awesome -->\r\n    <link rel=\"stylesheet\" href=\"https://use.fontawesome.com/releases/v5.8.2/css/all.css\">\r\n    <!-- Google Fonts -->\r\n    <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css?family=Roboto:300,400,500,700&display=swap\">\r\n    <!-- Bootstrap core CSS -->\r\n    <link href=\"https://cdnjs.cloudflare.com/ajax/libs/twitter-bootstrap/4.4.1/css/bootstrap.min.css\" rel=\"stylesheet\">\r\n    <!-- Material Design Bootstrap -->\r\n    <link href=\"https://cdnjs.cloudflare.com/ajax/libs/mdbootstrap/4.14.0/css/mdb.min.css\" rel=\"stylesheet\">\r\n    <link rel=\"stylesheet\" href=\"https://maxcdn.bootstrapcdn.com/font-awesome/4.7.0/css/font-awesome.min.css\">\r\n    <!-- Emoji Picker -->\r\n    <link href=\"http://onesignal.github.io/emoji-picker/lib/css/emoji.css\" rel=\"stylesheet\">\r\n    <!-- MDBootstrap Datatables  -->\r\n    <link href=\"https://cdn.datatables.net/1.10.20/css/jquery.dataTables.css\" rel=\"stylesheet\">\r\n\r\n    <style type=\"text/css\">\r\n        .container {\r\n            width: 75% !important;\r\n        }\r\n        .row {\r\n            width: 100% !important;\r\n        }\r\n\r\n        .EF_Header {\r\n            background-color: #4a8bbf;\r\n            padding: 10px;\r\n            width: 100%;\r\n            border-bottom: 10px solid #fbbf0c;\r\n        }\r\n\r\n        .EF_Logo{\r\n            background-image: url(\"https://pixelzone.us/kernel/includes/pages/developer_build/websockets/ws_overlays/Internet/resources/images/eyefind-logo.png\");\r\n            background-size: 200px;\r\n            background-repeat: no-repeat;\r\n            height: 90px;\r\n            width: 200px;\r\n        }\r\n\r\n        .EF_Time {\r\n            color: white;\r\n            text-align: right;\r\n            right: 0;\r\n        }\r\n\r\n        .EF_Time .icon {\r\n            color: #f6c00a;\r\n            font-size: 40px;\r\n        }\r\n\r\n        .vertical-center {\r\n          margin: 0;\r\n          position: absolute;\r\n          top: 50%;\r\n          -ms-transform: translateY(-50%);\r\n          transform: translateY(-50%);\r\n        }\r\n\r\n        .EF_SearchBar i { \r\n            position: absolute; \r\n        } \r\n          \r\n        .EF_SearchBar{ \r\n            padding-left: 40px;\r\n        } \r\n          \r\n        .EF_SearchBar .icon { \r\n            padding: 4px 4px 4px 10px;\r\n            /* min-width: 40px; */\r\n            font-size: 30px;\r\n            color: #638ab6; \r\n        } \r\n          \r\n        .EF_SearchBar .input-field {\r\n            padding: 7px 7px 7px 45px;\r\n            width: 100%;\r\n            border: 1px solid grey;\r\n        }\r\n\r\n        .EF_Btn_Random {\r\n            padding: 5px;\r\n            width: 100%;\r\n            font-size: 20px;\r\n            color: white;\r\n            background-color: #05728d;\r\n            border: 0;\r\n            border-radius: 5px;\r\n            outline: none;\r\n        }\r\n\r\n        .EF_Btn_Random:hover {\r\n            background-color: #0683a2;\r\n        }\r\n\r\n        .EF_Btn_Random:active {\r\n            background-color: #04657d;\r\n        }\r\n\r\n        .EF_Nav {\r\n            background-color: #f0f0f0;\r\n            padding:0;\r\n            padding-left:27px;\r\n            border-top:1px solid #b7b7b7;\r\n            border-bottom:1px solid #b7b7b7;\r\n        }\r\n        .EF_Nav .container {\r\n            width: 69.2% !important;\r\n            padding: 0;\r\n        }\r\n        .EF_Nav .nav-item{\r\n            padding-left: 15px;\r\n            padding-right: 15px;\r\n        }\r\n        .EF_Nav .nav-item:hover {\r\n            background-color: #eaeaea;\r\n        }\r\n        .EF_Nav .container .icon {\r\n            font-size: 30px;\r\n            color: #638ab6;\r\n            margin-left: 10px;\r\n        }\r\n\r\n        .EF_Body {\r\n            padding-left:27px;\r\n        }\r\n\r\n        .EF_Body .container {\r\n            width: 69.2% !important;\r\n            padding: 0;\r\n            padding-top: 20px;\r\n        }\r\n\r\n        .EF_Body .container .row {\r\n            padding:0;\r\n            margin: 0;\r\n        }\r\n\r\n        .ef-content-box {\r\n            background-color: #f3f3f3;\r\n            text-align: left;\r\n            padding: 10px;\r\n            margin-bottom: 10px;\r\n        }\r\n\r\n        .ef-ad-blue {\r\n            background-color: #4f91c2;\r\n            font-size: 14px;\r\n            color:white;\r\n            text-align: center;\r\n        }\r\n\r\n        .EF_title_box {\r\n            font-size: 18px;\r\n        }\r\n\r\n        .EF_footer_box {\r\n            font-size: 16px;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n\r\n    <!-- HEADER -->\r\n    <nav class=\"navbar EF_Header justify-content-between\">\r\n        <div class=\"container\">\r\n            <div class=\"row\">\r\n                <div class=\"col-9\">\r\n                    <div class=\"EF_Logo\"></div>\r\n                </div>\r\n                <div class=\"col-3\">\r\n                    <div class=\"EF_Time vertical-center\">\r\n                        <table>\r\n                            <tr>\r\n                                <td style=\"border-right: 1px solid white;padding-right: 10px;\">Jeihden</td>\r\n                                <td rowspan=\"2\" style=\"padding-left: 20px;\"><i class=\"fa fa-sun-o icon\"></i></td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td style=\"padding-right: 10px;\">Sat</td>\r\n                            </tr>\r\n                        </table>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"row\">\r\n                <div class=\"col-10\">\r\n                    <div class=\"EF_SearchBar\">\r\n                        <i class=\"fa fa-search icon\"></i> \r\n                        <input class=\"input-field\" type=\"text\" placeholder=\"Buscar en Eyefind\">\r\n                    </div>\r\n                </div>\r\n                <div class=\"col-2\" style=\"padding: 0 !important;\">\r\n                    <button class=\"EF_Btn_Random\">ALEATORIO</button>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </nav>\r\n    <!-- END HEADER -->\r\n\r\n    <!-- NAV -->\r\n    <nav class=\"navbar EF_Nav navbar-expand-lg\">\r\n        <div class=\"container\">\r\n            <ul class=\"navbar-nav mr-auto mt-lg-0 border-right\">\r\n                <li class=\"nav-item nav-link waves-effect waves-light\">\r\n                    <table style=\"border-collapse: inherit !important;\">\r\n                        <tr>\r\n                            <td><i class=\"fa fa-tablet icon\" style=\"font-size: 39px;\"></i></td>\r\n                            <td class=\"text-center\">MEDIOS Y ENTRETENIMIENTO</td>\r\n                        </tr>\r\n                    </table>\r\n                </li>\r\n            </ul>\r\n            <ul class=\"navbar-nav mr-auto mt-lg-0 border-right\">\r\n                <li class=\"nav-item nav-link waves-effect waves-light\">\r\n                    <table style=\"border-collapse: inherit !important;\">\r\n                        <tr>\r\n                            <td><i class=\"fa fa-cutlery icon\"></i></i></td>\r\n                            <td class=\"text-center\">COMIDA Y BEBIDA</td>\r\n                        </tr>\r\n                    </table>\r\n                </li>\r\n            </ul>\r\n            <ul class=\"navbar-nav mr-auto mt-lg-0 border-right\">\r\n                <li class=\"nav-item nav-link waves-effect waves-light\">\r\n                    <table style=\"border-collapse: inherit !important;\">\r\n                        <tr>\r\n                            <td><i class=\"fa fa-money icon\" style=\"font-size: 36px;\"></i></td>\r\n                            <td class=\"text-center\">DINERO Y SERVICIOS</td>\r\n                        </tr>\r\n                    </table>\r\n                </li>\r\n            </ul>\r\n            <ul class=\"navbar-nav mr-auto mt-lg-0 border-right\">\r\n                <li class=\"nav-item nav-link waves-effect waves-light\">\r\n                    <table style=\"border-collapse: inherit !important;\">\r\n                        <tr>\r\n                            <td><i class=\"fa fa-plane icon\" style=\"font-size: 39px;\"></i></td>\r\n                            <td class=\"text-center\">VIAJES Y TRANSPORTE</td>\r\n                        </tr>\r\n                    </table>\r\n                </li>\r\n            </ul>\r\n            <ul class=\"navbar-nav mr-auto mt-lg-0\">\r\n                <li class=\"nav-item nav-link waves-effect waves-light\">\r\n                    <table style=\"border-collapse: inherit !important;\">\r\n                        <tr>\r\n                            <td><i class=\"fa fa-shopping-bag icon\"></i></td>\r\n                            <td class=\"text-center\">MODA Y SALUD</td>\r\n                        </tr>\r\n                    </table>\r\n                </li>\r\n            </ul>\r\n        </div>\r\n    </nav>\r\n    <!-- END NAV -->\r\n\r\n    <div class=\"EF_Body\">\r\n        <div class=\"container\">\r\n            <div class=\"row\">\r\n                \r\n                <div class=\"col-8\" style=\"padding-left:0;\">\r\n                    <div class=\"ef-content-box\">\r\n                        <div class=\"EF_title_box\">NOTICIA DEL D&Iacute;A</div>\r\n                        <br>\r\n                        <label style=\"font-weight: bold\">PixelZone se encuentra en una crisis de seguridad policial</label>\r\n                        <br>\r\n                        <br>\r\n                        <p style=\"font-size: 14px;\">\r\n                            Tras los eventos ocurridos por corrupci&oacute;n en el gabinite policial de la ciudad de PixelZone, se han retirado todos los cargos. Lo cual, ha causado disturbios criminales en toda la ciudad y signifca poca seguridad para la integridad de sus ciudadanos.\r\n                        </p>\r\n                        <br>\r\n                        <div class=\"EF_footer_box\">LEER EL ART&Iacute;CULO COMPLETO</div>\r\n                    </div>\r\n\r\n                    <div class=\"ef-content-box\">\r\n                        <div class=\"EF_title_box\">SITIO WEB DEL MINUTO</div>\r\n                        <br>\r\n                        {web_site}\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"col-4\" style=\"padding-left:0;padding-right: 0;\">\r\n                    <div class=\"ef-content-box ef-ad-blue\">\r\n                        <label>ANUNCIO PATROCINADO</label>\r\n                        <div style=\"height: 96px;\"></div>\r\n                    </div>\r\n\r\n                    <div class=\"ef-content-box\">\r\n                        <div class=\"EF_title_box\">BLEETS RECIENTES</div>\r\n                        <br>\r\n                        {GET_BLEETS}\r\n                        <br><br><br>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"col-12\" style=\"padding-left:0;padding-right: 0;\">\r\n                    <div class=\"ef-content-box\">\r\n                        <div class=\"EF_title_box\">SITIOS WEB DESTACADOS POR EYEFIND</div>\r\n                        <br>\r\n                        {web_sites}\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- JQuery -->\r\n    <script type=\"text/javascript\" src=\"https://cdnjs.cloudflare.com/ajax/libs/jquery/3.4.1/jquery.min.js\"></script>\r\n    <!-- Bootstrap tooltips -->\r\n    <script type=\"text/javascript\" src=\"https://cdnjs.cloudflare.com/ajax/libs/popper.js/1.14.4/umd/popper.min.js\"></script>\r\n    <!-- Bootstrap core JavaScript -->\r\n    <script type=\"text/javascript\" src=\"https://cdnjs.cloudflare.com/ajax/libs/twitter-bootstrap/4.4.1/js/bootstrap.min.js\"></script>\r\n    <!-- MDB core JavaScript -->\r\n    <script type=\"text/javascript\" src=\"https://cdnjs.cloudflare.com/ajax/libs/mdbootstrap/4.14.0/js/mdb.min.js\"></script>\r\n</body>\r\n</html>');
