(8, 'Calculator', 'Calculadora', '/app/View/Directory/Client/websockets/ws_overlays/Phones/iPhone/resources/images/apps/Calculator.png', 'Jeihden', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\'utf-8\'>\r\n    <meta http-equiv=\'X-UA-Compatible\' content=\'IE=edge\'>\r\n    <title>Calculadora</title>\r\n    <meta name=\'viewport\' content=\'width=device-width, initial-scale=1\'>\r\n\r\n    <!-- Font Awesome -->\r\n    <link rel=\"stylesheet\" href=\"https://use.fontawesome.com/releases/v5.8.2/css/all.css\">\r\n    <!-- Google Fonts -->\r\n    <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css?family=Roboto:300,400,500,700&display=swap\">\r\n    <!-- Bootstrap core CSS -->\r\n    <link href=\"https://cdnjs.cloudflare.com/ajax/libs/twitter-bootstrap/4.4.1/css/bootstrap.min.css\" rel=\"stylesheet\">\r\n    <!-- Material Design Bootstrap -->\r\n    <link href=\"https://cdnjs.cloudflare.com/ajax/libs/mdbootstrap/4.14.0/css/mdb.min.css\" rel=\"stylesheet\">\r\n    <link rel=\"stylesheet\" href=\"https://maxcdn.bootstrapcdn.com/font-awesome/4.4.0/css/font-awesome.min.css\">\r\n\r\n    <style>\r\n        html, body, .container-fluid {\r\n            margin: 0;\r\n            padding: 0;\r\n            overflow: hidden;\r\n        }\r\n        /* CALCULADORA */\r\n        .app_Calculator form {\r\n          background: #999a9c;\r\n          padding-left: 15px;\r\n          padding-right: 7px;\r\n          width: 100%;\r\n        }\r\n        .app_Calculator input[type=textfield] {\r\n            height: 96px;\r\n            padding: 16px;\r\n            border: 0px;\r\n            text-align: right;\r\n            background: #636363;\r\n            color:white;\r\n            font-size: 45px;\r\n            font-weight: 100;\r\n            width: 100%;\r\n            margin-bottom: 5px;\r\n        }\r\n        .app_Calculator input[type=button], input[type=submit], input[type=reset] {\r\n            background-color: #f48915;\r\n            border: none;\r\n            color: white;\r\n            padding: 20px;\r\n            min-width: 23%;\r\n            margin-bottom: 2px;\r\n            text-decoration: none;\r\n            cursor: pointer;\r\n            font-size: 16px;\r\n            outline: none;\r\n        }\r\n        .app_Calculator input[type=button]:hover, input[type=submit]:hover, input[type=reset]:hover {\r\n          background-color: #333;\r\n        }\r\n        .wrapper{\r\n            width: 244px;\r\n            height: 368px;\r\n            margin: 0;\r\n            background: #999a9c;\r\n        }\r\n        /* END CALCULADORA */\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"wrapper\">\r\n    <div class=\"container-fluid\">\r\n        <div class=\"row\">\r\n            <div class=\"app_Calculator\">\r\n                <form name=\"calculator\">\r\n                    <div class=\"row\">\r\n                        <div class=\"col-12\">\r\n                            <input type=\"textfield\" name=\"ans\" value=\"\" autocomplete=\"off\" readonly>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"row\">\r\n                        <div class=\"col-12\">\r\n                            <input type=\"button\" value=\"7\" onClick=\"document.calculator.ans.value+=\'7\'\" style=\"background-color:#c7ccd6;color:black;\">\r\n                            <input type=\"button\" value=\"8\" onClick=\"document.calculator.ans.value+=\'8\'\" style=\"background-color:#c7ccd6;color:black;\">\r\n                            <input type=\"button\" value=\"9\" onClick=\"document.calculator.ans.value+=\'9\'\" style=\"background-color:#c7ccd6;color:black;\">\r\n                            <input type=\"button\" value=\"+\" onClick=\"document.calculator.ans.value+=\'+\'\">\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"row\">\r\n                        <div class=\"col-12\">\r\n                            <input type=\"button\" value=\"4\" onClick=\"document.calculator.ans.value+=\'4\'\" style=\"background-color:#c7ccd6;color:black;\">\r\n                            <input type=\"button\" value=\"5\" onClick=\"document.calculator.ans.value+=\'5\'\" style=\"background-color:#c7ccd6;color:black;\">\r\n                            <input type=\"button\" value=\"6\" onClick=\"document.calculator.ans.value+=\'6\'\" style=\"background-color:#c7ccd6;color:black;\">\r\n                            <input type=\"button\" value=\"-\" onClick=\"document.calculator.ans.value+=\'-\'\">\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"row\">\r\n                        <div class=\"col-12\">\r\n                            <input type=\"button\" value=\"1\" onClick=\"document.calculator.ans.value+=\'1\'\" style=\"background-color:#c7ccd6;color:black;\">\r\n                            <input type=\"button\" value=\"2\" onClick=\"document.calculator.ans.value+=\'2\'\" style=\"background-color:#c7ccd6;color:black;\">\r\n                            <input type=\"button\" value=\"3\" onClick=\"document.calculator.ans.value+=\'3\'\" style=\"background-color:#c7ccd6;color:black;\">\r\n                            <input type=\"button\" value=\"X\" onClick=\"document.calculator.ans.value+=\'*\'\">\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"row\">\r\n                        <div class=\"col-12\">\r\n                            <input type=\"button\" value=\"0\" onClick=\"document.calculator.ans.value+=\'0\'\" style=\"background-color:#c7ccd6;color:black;\">\r\n                            <input type=\"reset\" value=\"C\">\r\n                            <input type=\"button\" value=\"=\" onClick=\"document.calculator.ans.value=eval(document.calculator.ans.value)\">\r\n                            <input type=\"button\" value=\"/\" onClick=\"document.calculator.ans.value+=\'/\'\">\r\n                        </div>\r\n                    </div>\r\n                </form>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n    <!-- JQuery -->\r\n    <script type=\"text/javascript\" src=\"https://cdnjs.cloudflare.com/ajax/libs/jquery/3.4.1/jquery.min.js\"></script>\r\n    <!-- Bootstrap tooltips -->\r\n    <script type=\"text/javascript\" src=\"https://cdnjs.cloudflare.com/ajax/libs/popper.js/1.14.4/umd/popper.min.js\"></script>\r\n    <!-- Bootstrap core JavaScript -->\r\n    <script type=\"text/javascript\" src=\"https://cdnjs.cloudflare.com/ajax/libs/twitter-bootstrap/4.4.1/js/bootstrap.min.js\"></script>\r\n    <!-- MDB core JavaScript -->\r\n    <script type=\"text/javascript\" src=\"https://cdnjs.cloudflare.com/ajax/libs/mdbootstrap/4.14.0/js/mdb.min.js\"></script>\r\n</body>\r\n</html>', 0, '1.0'),
